$(function(){var observer=new MutationObserver(function(){var popup=document.querySelector('.swal2-popup'),title=popup&&popup.querySelector('.swal2-title');if(!popup||!title||title.textContent.trim()!=='Konfirmasi perubahan Moodle'||popup.querySelector('.apply-modal-head'))return;var add=parseInt($('#stat-add').text(),10)||0,remove=parseInt($('#stat-remove').text(),10)||0,html='<div class="apply-modal-head"><i class="fas fa-shield-halved"></i><div><strong>Preview sudah siap, Moodle belum diubah</strong><small>Perubahan hanya dikirim setelah semua checklist persetujuan dicentang.</small></div></div><div class="apply-modal-summary"><div><i class="fas fa-user-plus"></i><span>Akan ditambah<b>'+add+' anggota</b></span></div><div><i class="fas fa-user-minus"></i><span>Akan dikeluarkan<b>'+remove+' anggota</b></span></div></div><div class="apply-modal-boundary"><b><i class="fas fa-lock mr-1"></i>Yang tidak berubah</b>Nilai, data akun, username/NISN, dan anggota manual Moodle tetap aman. Sistem hanya mengelola membership yang terdeteksi dari SIMANSA.</div><div class="apply-modal-check-title">Persetujuan wajib</div>';var warning=popup.querySelector('.alert');if(warning)warning.insertAdjacentHTML('beforebegin',html);else{var container=popup.querySelector('.swal2-html-container');if(container)container.insertAdjacentHTML('afterbegin',html);}var summary=popup.querySelector('.small.text-muted');if(summary)summary.style.display='none';});observer.observe(document.body,{childList:true,subtree:true});});
